//! Shared corpus access, shapes/levels vocabulary and correctness gates.

use std::{fs, path::PathBuf};

use clap::ValueEnum as _;
use zstdx::{DecoderOptions, EncoderOptions, Level, decoding::FrameDecoder};

/// Corpus shapes generated by `bench/gen_corpus.sh` (32 MiB each).
#[derive(Debug, Clone, Copy, PartialEq, Eq, clap::ValueEnum)]
pub enum Shape {
    /// Semi-structured records.
    Json,
    /// Source tree tiled: long-range repeats.
    Text,
    /// 16-byte alphabet: heavy short matches.
    Skewed,
    /// Incompressible.
    Random,
    /// Maximally redundant.
    Zeros,
}

impl Shape {
    pub const fn raw_name(self) -> &'static str {
        match self {
            Shape::Json => "json",
            Shape::Text => "text",
            Shape::Skewed => "skewed",
            Shape::Random => "random",
            Shape::Zeros => "zeros",
        }
    }
}

pub const SHAPES: [Shape; 5] = [
    Shape::Json,
    Shape::Text,
    Shape::Skewed,
    Shape::Random,
    Shape::Zeros,
];

/// Our level ladder bench-matched against libzstd levels.
#[derive(Debug, Clone, Copy, PartialEq, Eq, clap::ValueEnum)]
pub enum LevelName {
    Fastest,
    Fast,
    Balanced,
    Best,
    Opt,
    Ultra,
}

impl LevelName {
    /// `(our level, matching libzstd level)` used by the A/B pairings.
    pub const fn pair(self) -> (Level, i32) {
        match self {
            LevelName::Fastest => (Level::Fastest, 1),
            LevelName::Fast => (Level::Fast, 3),
            LevelName::Balanced => (Level::Balanced, 9),
            LevelName::Best => (Level::Best, 13),
            LevelName::Opt => (Level::Opt, 17),
            LevelName::Ultra => (Level::Ultra, 19),
        }
    }

    /// Lowercase row/tag name shared by the bench outputs.
    pub const fn tag(self) -> &'static str {
        match self {
            LevelName::Fastest => "fastest",
            LevelName::Fast => "fast",
            LevelName::Balanced => "balanced",
            LevelName::Best => "best",
            LevelName::Opt => "opt",
            LevelName::Ultra => "ultra",
        }
    }
}

pub const LADDER: [LevelName; 6] = [
    LevelName::Fastest,
    LevelName::Fast,
    LevelName::Balanced,
    LevelName::Best,
    LevelName::Opt,
    LevelName::Ultra,
];

/// A `--level` value of the matrix benches: a ladder tier name or a numeric
/// level (1-22). On tier axes a number must land on a tier; on the numeric
/// `--full-ladder` axis a tier name selects its own level.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LevelSel {
    Tier(LevelName),
    Num(Level),
}

impl LevelSel {
    /// The numeric level denoted: the tier's own level or the number.
    pub const fn numeric(self) -> Level {
        match self {
            LevelSel::Tier(t) => t.pair().0,
            LevelSel::Num(l) => l,
        }
    }

    /// The tier denoted, if the number is one of the tier levels.
    pub fn tier(self) -> Option<LevelName> {
        match self {
            LevelSel::Tier(t) => Some(t),
            LevelSel::Num(l) => LADDER.iter().copied().find(|t| t.pair().0 == l),
        }
    }
}

impl std::str::FromStr for LevelSel {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, String> {
        if let Ok(n) = s.parse::<i32>() {
            let (lo, hi) = (Level::Fastest.as_i32(), Level::MAX.as_i32());
            if (lo..=hi).contains(&n) {
                return Ok(LevelSel::Num(Level::from_zstd(n)));
            }
            return Err(format!("numeric level {n} out of range {lo}-{hi}"));
        }
        if let Ok(tier) = LevelName::from_str(s, false) {
            return Ok(LevelSel::Tier(tier));
        }
        let tiers = LADDER.iter().map(|t| t.tag()).collect::<Vec<_>>().join("/");
        Err(format!(
            "invalid level `{s}`: expected a tier ({tiers}) or a numeric level (1-22)"
        ))
    }
}

/// Tier-axis selection: tier names match themselves, numbers the tier at
/// that level. Empty selection means every tier.
pub fn want_tier(selected: &[LevelSel], t: &LevelName) -> bool {
    selected.is_empty() || selected.iter().any(|s| s.numeric() == t.pair().0)
}

/// Numeric-axis selection: numbers match themselves, tier names their own
/// level. Empty selection means every level 1-22.
pub fn want_number(selected: &[LevelSel], n: i32) -> bool {
    selected.is_empty() || selected.iter().any(|s| s.numeric().as_i32() == n)
}

pub fn corpus_dir() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    dir.push("../../bench/corpus");
    dir
}

/// Load a corpus file and its raw counterpart (`json.zst3` -> `json.raw`).
pub fn load(name: &str) -> (Vec<u8>, Vec<u8>) {
    let dir = corpus_dir();
    let compressed = fs::read(dir.join(name)).unwrap();
    let raw = fs::read(dir.join(format!("{}.raw", name.split('.').next().unwrap()))).unwrap();
    (compressed, raw)
}

pub fn load_raw(shape: Shape) -> Vec<u8> {
    fs::read(corpus_dir().join(format!("{}.raw", shape.raw_name()))).unwrap()
}

// ---------- correctness gates (run before anything is timed) ----------

pub fn gate_ruz_dec(compressed: &[u8], raw: &[u8], label: &str) {
    let mut out = vec![0u8; raw.len()];
    FrameDecoder::new()
        .decode_all(compressed, &mut out)
        .unwrap_or_else(|e| panic!("zstdx decode gate failed for {label}: {e}"));
    assert_eq!(&out[..], raw, "zstdx gate mismatch for {label}");
}

pub fn gate_ruz_mt_dec(compressed: &[u8], raw: &[u8], threads: u32, label: &str) {
    let mut out = vec![0u8; raw.len()];
    zstdx::bulk::decompress_to_buffer_with(
        compressed,
        &mut out,
        &DecoderOptions::new().threads(threads),
    )
    .unwrap_or_else(|e| panic!("zstdx MT decode gate failed for {label}: {e}"));
    assert_eq!(&out[..], raw, "zstdx MT gate mismatch for {label}");
}

pub fn gate_zstd_dec(compressed: &[u8], raw: &[u8], label: &str) {
    let mut decoded = Vec::new();
    zstd::stream::copy_decode(compressed, &mut decoded).unwrap();
    assert_eq!(&decoded[..], raw, "zstd gate mismatch for {label}");
}

pub fn gate_ruz_enc(raw: &[u8], level: Level, label: &str) -> Vec<u8> {
    let comp =
        zstdx::bulk::compress_with(raw, &EncoderOptions::new(level).checksum(false)).unwrap();
    let mut back = Vec::with_capacity(raw.len() + 16);
    FrameDecoder::new()
        .decode_all_to_vec(&comp, &mut back)
        .unwrap();
    assert_eq!(&back[..], raw, "zstdx encode gate mismatch for {label}");
    comp
}

pub fn gate_zstd_enc(raw: &[u8], level: i32, label: &str) -> Vec<u8> {
    let comp = zstd::bulk::compress(raw, level).unwrap();
    let mut back = Vec::new();
    zstd::stream::copy_decode(comp.as_slice(), &mut back).unwrap();
    assert_eq!(&back[..], raw, "zstd encode gate mismatch for {label}");
    comp
}

/// Both decoders must accept the frame and reproduce the raw input.
pub fn assert_roundtrip(comp: &[u8], raw: &[u8], label: &str) {
    let mut back = Vec::new();
    zstd::stream::copy_decode(comp, &mut back).unwrap();
    assert_eq!(&back[..], raw, "roundtrip mismatch for {label}");
    let mut back2 = Vec::with_capacity(raw.len() + 16);
    FrameDecoder::new()
        .decode_all_to_vec(comp, &mut back2)
        .unwrap();
    assert_eq!(&back2[..], raw, "zstdx roundtrip mismatch for {label}");
}
